    const withdrawn = (wd.data ?? []).filter((w) => w.status !== "rejected").reduce((s, w) => s + Number(w.amount_usd || 0), 0);
    const balanceUsd = Math.max(0, deposited - withdrawn);
    const balanceKes = Math.round(balanceUsd * EXCHANGE_RATE);
    return {
      content: [{ type: "text", text: `Available balance: $${balanceUsd.toFixed(2)} (\u2248 KES ${balanceKes})` }],
      structuredContent: { balance_usd: balanceUsd, balance_kes: balanceKes }
    };
